using System.Collections.Generic;
using UnityEngine;

// Author : Baptiste Vu Liem
namespace Com.IsartDigital.GoobyrFPS.Audio
{
    /// <summary>
    /// Plays the procedural sound effects (generated by the SFX builder into
    /// <c>Resources/Sfx</c>) from a pool of 3D audio sources. Missing clips are silently skipped.
    /// </summary>
    public static class Sfx
    {
        private const int POOL = 48;
        private static readonly Dictionary<string, AudioClip[]> _clips = new Dictionary<string, AudioClip[]>();
        private static AudioSource[] _pool;
        private static int _next;
        private static Transform _root;

        public static float Volume
        {
            get => PlayerPrefs.GetFloat("goobyr.sfx", 0.8f);
            set => PlayerPrefs.SetFloat("goobyr.sfx", value);
        }

        private static AudioClip Clip(string pName)
        {
            if (!_clips.TryGetValue(pName, out AudioClip[] lVariants))
            {
                List<AudioClip> lFound = new List<AudioClip>();
                AudioClip lBase = Resources.Load<AudioClip>("Sfx/" + pName);
                if (lBase != null) lFound.Add(lBase);
                for (int i = 1; i < 6; i++)
                {
                    AudioClip lVariant = Resources.Load<AudioClip>("Sfx/" + pName + "_" + i);
                    if (lVariant != null) lFound.Add(lVariant);
                }
                lVariants = lFound.ToArray();
                _clips[pName] = lVariants;
            }
            return lVariants.Length == 0 ? null : lVariants[Random.Range(0, lVariants.Length)];
        }

        private static void EnsurePool()
        {
            if (_root != null) return;
            _root = new GameObject("SfxPool").transform;
            Object.DontDestroyOnLoad(_root.gameObject);
            _pool = new AudioSource[POOL];
            for (int i = 0; i < POOL; i++)
            {
                AudioSource lSource = new GameObject("Sfx" + i).AddComponent<AudioSource>();
                lSource.transform.SetParent(_root);
                lSource.playOnAwake = false;
                lSource.spatialBlend = 1f;
                // Logarithmic falloff (how sound fades outdoors), reaching silence at the given range.
                lSource.rolloffMode = AudioRolloffMode.Logarithmic;
                lSource.minDistance = 2f;
                lSource.maxDistance = 70f;
                lSource.dopplerLevel = 0f;
                _pool[i] = lSource;
            }
        }

        /// <summary>A 3D sound at a point. <paramref name="pRange"/> is how far it carries.</summary>
        public static void Play(string pName, Vector3 pPosition, float pVolume = 1f, float pRange = 70f, float pPitchJitter = 0.08f)
        {
            AudioClip lClip = Clip(pName);
            if (lClip == null) return;
            EnsurePool();
            AudioSource lSource = _pool[_next];
            _next = (_next + 1) % POOL;
            lSource.transform.position = pPosition;
            lSource.clip = lClip;
            lSource.volume = pVolume * Volume;
            lSource.maxDistance = pRange;
            lSource.minDistance = Mathf.Clamp(pRange / 14f, 0.8f, 8f);
            lSource.spatialBlend = 1f;
            lSource.pitch = 1f + Random.Range(-pPitchJitter, pPitchJitter);
            lSource.Play();
        }

        /// <summary>A flat UI / first-person sound.</summary>
        public static void Play2D(string pName, float pVolume = 1f, float pPitchJitter = 0.04f)
        {
            AudioClip lClip = Clip(pName);
            if (lClip == null) return;
            EnsurePool();
            AudioSource lSource = _pool[_next];
            _next = (_next + 1) % POOL;
            lSource.clip = lClip;
            lSource.volume = pVolume * Volume;
            lSource.spatialBlend = 0f;
            lSource.pitch = 1f + Random.Range(-pPitchJitter, pPitchJitter);
            lSource.Play();
        }
    }
}
